# Compare two JSON objects and return `True` if equal, `False` if not
def compare_json_objects(first_obj, second_obj):
    first_obj_str = json.dumps(first_obj)
    second_obj_str = json.dumps(second_obj)
    if first_obj_str == second_obj_str:
        return True
    else:
        return False

if __name__ == '__main__':
