### Instruction:
Implement a Go program that takes a string as input and prints its reverse.

### Response:
package main

import "fmt"

func main() {
    var str string
    fmt.Printf("Enter a string: ")
    fmt.Scanf("%s\n", &str)
    fmt.Printf("The reverse of the string is %s\n", reverse(str))
}

func reverse(s string) string {
    r := []rune(s)
    for i, j := 0, len(r)-1; i < len(r)/2; i, j = i+1, j-1 {
        r[i], r[j] = r[j], r[i]
    }
    return string(r)
}

### Instruction:
Given a two-dimensional array of integers, find the maximum sum of numbers you can find by tracing a path from the top-left to bottom-right corner.

### Input:
[[1, 5, 4], [2, 3, 4], [1, 9, 3]]

### Response:
def max_sum(arr):
    result = [[None] * len(arr[0]) for _ in range(len(arr))]
    result[0][0] = arr[0][0]
    for i in range(1, len(arr[0])):
        result[0][i] = arr[0][i] + result[0][i - 1]
    for i in range(1, len(arr)):
        result[i][0] = arr[i][0] + result[i - 1][0]
    for i in range(1, len(arr)):
        for j in range(1, len(arr[0])):
            result[i][j] = max(result[i - 1][j], result[i][j - 1]) + arr[i][j]
    return result[- 1][- 1]

if __name__ == '__main__':
    arr = [[1, 5, 4], [2, 3, 4], [1, 9, 3]]
    print(max_sum(arr))

